namespace EduVerse.Core.Curriculum;

/// <summary>A concept to learn, with the concepts that must be understood before it.</summary>
public sealed record Concept(string Key, string Name, string Description, IReadOnlyList<string> Prerequisites);

/// <summary>A subject as an ordered map of concepts (built-in or generated by the AI from a topic).</summary>
public sealed record Subject(string Key, string Name, string Area, IReadOnlyList<Concept> Concepts, bool BuiltIn)
{
    public const int MaxConcepts = 20;

    public Concept? Find(string key) => Concepts.FirstOrDefault(c => c.Key == key);

    /// <summary>Concepts in an order where prerequisites always come first (stable on the declared order).</summary>
    public IReadOnlyList<Concept> Ordered()
    {
        var done = new HashSet<string>();
        var result = new List<Concept>();
        var pending = Concepts.ToList();
        while (pending.Count > 0)
        {
            var next = pending.FirstOrDefault(c => c.Prerequisites.All(p => done.Contains(p) || Concepts.All(x => x.Key != p))) ?? pending[0];
            result.Add(next);
            done.Add(next.Key);
            pending.Remove(next);
        }

        return result;
    }
}

/// <summary>Validates a concept map (from the AI or a teacher): unique keys, known prerequisites, no cycles.</summary>
public static class ConceptMapValidator
{
    public static IReadOnlyList<string> Check(IReadOnlyList<Concept> concepts)
    {
        ArgumentNullException.ThrowIfNull(concepts);
        var errors = new List<string>();
        if (concepts.Count is 0 or > Subject.MaxConcepts)
        {
            errors.Add("concept_count");
        }

        var keys = concepts.Select(c => c.Key).ToList();
        if (keys.Distinct().Count() != keys.Count)
        {
            errors.Add("duplicate_key");
        }

        if (concepts.Any(c => c.Prerequisites.Any(p => !keys.Contains(p) || p == c.Key)))
        {
            errors.Add("unknown_prerequisite");
        }

        // Cycle detection (depth-first)
        var state = new Dictionary<string, int>();
        bool Cycle(string key)
        {
            if (state.TryGetValue(key, out var s))
            {
                return s == 1;
            }

            state[key] = 1;
            var c = concepts.FirstOrDefault(x => x.Key == key);
            if (c is not null && c.Prerequisites.Where(keys.Contains).Any(Cycle))
            {
                return true;
            }

            state[key] = 2;
            return false;
        }

        if (keys.Distinct().Any(Cycle))
        {
            errors.Add("cycle");
        }

        return errors;
    }
}
